CREATE OR REPLACE FUNCTION public.check_goods_in_storage_unit(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
-- Goods-in inspection hold (spec .ai/specs/2026-11-03-goods-in-inspection-hold.md).
-- A location's inspection and rejected storage units stay active and
-- non-nettable: held stock in a nettable unit would be offered to MRP and
-- picking, and an inactive unit cannot be picked for a receipt line. Every
-- change of effectiveNettable is written by util.refresh_storage_unit_nettable
-- as an UPDATE of the unit, so a change of the unit's own flag, a parent's or a
-- storage type's reaches this check. It stays at the location that names it,
-- where its lots and ledger rows are booked. A plain RAISE (P0001), so the API
-- shows the text.
DECLARE
  v_location TEXT;
  v_becomes_nettable BOOLEAN;
  v_deactivated BOOLEAN;
  v_moved BOOLEAN;
BEGIN
  IF p_operation <> 'UPDATE' THEN
    RETURN;
  END IF;
  v_becomes_nettable := COALESCE((p_new->>'effectiveNettable')::boolean, true)
    AND NOT COALESCE((p_old->>'effectiveNettable')::boolean, true);
  v_deactivated := COALESCE((p_old->>'active')::boolean, true)
    AND NOT COALESCE((p_new->>'active')::boolean, true);
  v_moved := (p_new->'locationId') IS DISTINCT FROM (p_old->'locationId');
  IF NOT v_becomes_nettable AND NOT v_deactivated AND NOT v_moved THEN
    RETURN;
  END IF;
  IF current_setting('app.inspection_release', true) = 'on'
     OR current_setting('app.sync_in_progress', true) = 'true' THEN
    RETURN;
  END IF;

  SELECT l."name" INTO v_location
  FROM "location" l
  WHERE l."companyId" = p_old->>'companyId'
    AND (l."inspectionStorageUnitId" = p_old->>'id' OR l."rejectedStorageUnitId" = p_old->>'id')
  ORDER BY l."name"
  LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION '% is a goods-in storage unit of %. Choose another unit in Settings → Quality first.',
      COALESCE(p_new->>'name', p_new->>'id'), v_location;
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.check_inspection_hold()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
-- Goods-in inspection hold (spec .ai/specs/2026-11-03-goods-in-inspection-hold.md).
-- Refuses a stock movement OUT of held stock: a serial or batch unit that is
-- On Hold while its receipt line's inspection lot is open, or untracked
-- quantity an open inspection lot holds at its storage unit. The postings that
-- ARE the release (the rejected move, the NCR write-off, a receipt void, an
-- inventory count, a return shipment) set app.inspection_release for their
-- transaction. A plain RAISE (P0001): the API passes its text to the person;
-- any other SQLSTATE reads as a server failure and is withheld.
DECLARE
  v_companies TEXT[];
  v_items     TEXT[];
  v_units     TEXT[];
  v_item_id   TEXT;
  v_unit      TEXT;
  v_item      TEXT;
  v_unit_name TEXT;
  i           INT;
BEGIN
  -- Stock leaves only through a new ledger row.
  IF TG_OP <> 'INSERT' THEN
    RETURN NULL;
  END IF;
  IF current_setting('app.inspection_release', true) = 'on'
     OR current_setting('app.sync_in_progress', true) = 'true' THEN
    RETURN NULL;
  END IF;

  -- Only an inspection hold: a unit On Hold for another reason (a customer
  -- return awaiting its RMA disposition) is not this guard's to refuse.
  SELECT b."itemId" INTO v_item_id
  FROM batched_new b
  JOIN "trackedEntity" te ON te."id" = b."trackedEntityId"
  JOIN "inspection" ins
    ON ins."sourceDocument" = 'Receipt'
   AND ins."sourceDocumentLineId" = te."attributes" ->> 'Receipt Line'
   AND ins."companyId" = te."companyId"
  WHERE b."quantity" < 0
    AND te."status" = 'On Hold'
    AND ins."status" IN ('Pending', 'In Progress')
  ORDER BY b."entryNumber"
  LIMIT 1;
  IF FOUND THEN
    SELECT "readableIdWithRevision" INTO v_item FROM "item" WHERE "id" = v_item_id;
    RAISE EXCEPTION '% is held for inspection. Quality must decide its inspection lot before it can move.',
      COALESCE(v_item, v_item_id);
  END IF;

  -- The (item, unit) pairs an untracked move takes stock from where a lot can
  -- hold stock. A Partial lot stops holding when its NCR closes (inspection_held_quantity).
  SELECT
    array_agg(k.c ORDER BY k.c, k.i, k.u),
    array_agg(k.i ORDER BY k.c, k.i, k.u),
    array_agg(k.u ORDER BY k.c, k.i, k.u)
  INTO v_companies, v_items, v_units
  FROM (
    SELECT DISTINCT b."companyId" AS c, b."itemId" AS i, b."storageUnitId" AS u
    FROM batched_new b
    WHERE b."quantity" < 0
      AND b."trackedEntityId" IS NULL
      AND b."storageUnitId" IS NOT NULL
      AND EXISTS (
        SELECT 1 FROM "inspection" h
        WHERE h."storageUnitId" = b."storageUnitId"
          AND h."itemId" = b."itemId"
          AND h."status" IN ('Pending', 'In Progress', 'Partial')
          AND public.inspection_lot_holds(h."id", h."status", h."acceptedQuantity")
      )
  ) k;
  IF v_units IS NULL THEN
    RETURN NULL;
  END IF;

  -- Two moves out of the same held (item, unit) must not both pass on the same
  -- on-hand: the second waits for the first to commit, then reads its rows.
  -- One order for every statement, so two statements cannot deadlock.
  FOR i IN 1 .. array_length(v_units, 1) LOOP
    PERFORM pg_advisory_xact_lock(
      hashtextextended('inspection-hold:' || v_companies[i] || ':' || v_items[i] || ':' || v_units[i], 0)
    );
  END LOOP;

  -- Held and on-hand from one snapshot, taken after the locks: read apart, a
  -- receipt committing between the two reads counts on one side only. On-hand
  -- already includes this statement's rows. Only untracked rows: serial and
  -- batch stock is held by its status, above.
  SELECT k.i, k.u INTO v_item_id, v_unit
  FROM unnest(v_companies, v_items, v_units) AS k(c, i, u)
  CROSS JOIN LATERAL (
    SELECT
      public.inspection_held_quantity(k.c, k.i, k.u) AS held,
      public.inspection_untracked_on_hand(k.c, k.i, k.u) AS on_hand
  ) s
  WHERE s.held > 0 AND s.on_hand < s.held
  ORDER BY k.c, k.i, k.u
  LIMIT 1;
  IF FOUND THEN
    SELECT "readableIdWithRevision" INTO v_item FROM "item" WHERE "id" = v_item_id;
    SELECT "name" INTO v_unit_name FROM "storageUnit" WHERE "id" = v_unit;
    RAISE EXCEPTION '% is held for inspection in %. Quality must decide its inspection lot before it can move.',
      COALESCE(v_item, v_item_id), COALESCE(v_unit_name, v_unit);
  END IF;
  RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION public.check_inspection_lot_release(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
-- Goods-in inspection hold (spec .ai/specs/2026-11-03-goods-in-inspection-hold.md).
-- A receipt lot's columns decide what check_inspection_hold holds, so a direct
-- edit or delete (PostgREST) could release held stock without moving it. Only
-- the postings that ARE the release (they set app.inspection_release) change
-- them; samples move an open lot between Pending and In Progress. A company
-- wipe, restore or import sets one of the two flags, and deleting the company
-- is never refused. A plain RAISE (P0001), so the API shows the text.
DECLARE
  v_holds BOOLEAN;
BEGIN
  IF p_operation NOT IN ('UPDATE', 'DELETE') THEN
    RETURN;
  END IF;
  IF p_old->>'sourceDocument' IS DISTINCT FROM 'Receipt'
     AND (p_operation = 'DELETE' OR p_new->>'sourceDocument' IS DISTINCT FROM 'Receipt') THEN
    RETURN;
  END IF;

  IF p_operation = 'DELETE' THEN
    -- Only a lot that holds stock: open, or Partial until its NCR closes.
    IF p_old->>'status' NOT IN ('Pending', 'In Progress', 'Partial')
       OR NOT public.inspection_lot_holds(
         p_old->>'id',
         (p_old->>'status')::"inspectionStatusType",
         (p_old->>'acceptedQuantity')::numeric
       ) THEN
      RETURN;
    END IF;
    IF current_setting('app.inspection_release', true) = 'on'
       OR current_setting('app.sync_in_progress', true) = 'true' THEN
      RETURN;
    END IF;
    -- A lot from before the hold (no storage unit) holds untracked stock
    -- nowhere; it holds serial or batch units only while they are On Hold.
    IF p_old->>'storageUnitId' IS NULL AND NOT (
      p_old->>'status' IN ('Pending', 'In Progress')
      AND EXISTS (
        SELECT 1 FROM "trackedEntity" te
        WHERE te."companyId" = p_old->>'companyId'
          AND te."attributes" ->> 'Receipt Line' = p_old->>'sourceDocumentLineId'
          AND te."status" = 'On Hold'
      )
    ) THEN
      RETURN;
    END IF;
    -- A company deletion cascades here after the company row is gone.
    IF NOT EXISTS (SELECT 1 FROM "company" c WHERE c."id" = p_old->>'companyId') THEN
      RETURN;
    END IF;
    RAISE EXCEPTION 'Inspection lot % holds stock. Quality must decide it before it can be deleted.',
      COALESCE(p_old->>'inspectionId', p_old->>'id');
  END IF;

  -- What the hold reads while the lot holds stock: open, or Partial until its
  -- NCR closes (a storage unit's delete may then clear the lot's unit).
  v_holds := p_old->>'status' IN ('Pending', 'In Progress', 'Partial')
    AND public.inspection_lot_holds(
      p_old->>'id',
      (p_old->>'status')::"inspectionStatusType",
      (p_old->>'acceptedQuantity')::numeric
    );
  IF (p_new->'status') IS NOT DISTINCT FROM (p_old->'status')
     AND (p_new->'sourceDocument') IS NOT DISTINCT FROM (p_old->'sourceDocument')
     AND (NOT v_holds OR (
       (p_new->'storageUnitId') IS NOT DISTINCT FROM (p_old->'storageUnitId')
       AND (p_new->'acceptedQuantity') IS NOT DISTINCT FROM (p_old->'acceptedQuantity')
       AND (p_new->'lotSize') IS NOT DISTINCT FROM (p_old->'lotSize')
       AND (p_new->'itemId') IS NOT DISTINCT FROM (p_old->'itemId')
       AND (p_new->'sourceDocumentLineId') IS NOT DISTINCT FROM (p_old->'sourceDocumentLineId')
     )) THEN
    RETURN;
  END IF;

  -- Samples recompute an open lot's status.
  IF p_old->>'status' IN ('Pending', 'In Progress')
     AND p_new->>'status' IN ('Pending', 'In Progress')
     AND (p_new->'sourceDocument') IS NOT DISTINCT FROM (p_old->'sourceDocument')
     AND (p_new->'storageUnitId') IS NOT DISTINCT FROM (p_old->'storageUnitId')
     AND (p_new->'acceptedQuantity') IS NOT DISTINCT FROM (p_old->'acceptedQuantity')
     AND (p_new->'lotSize') IS NOT DISTINCT FROM (p_old->'lotSize')
     AND (p_new->'itemId') IS NOT DISTINCT FROM (p_old->'itemId')
     AND (p_new->'sourceDocumentLineId') IS NOT DISTINCT FROM (p_old->'sourceDocumentLineId') THEN
    RETURN;
  END IF;

  IF current_setting('app.inspection_release', true) = 'on'
     OR current_setting('app.sync_in_progress', true) = 'true' THEN
    RETURN;
  END IF;
  -- A company deletion's cascade (a storage unit's SET NULL) after the
  -- company row is gone.
  IF NOT EXISTS (SELECT 1 FROM "company" c WHERE c."id" = p_old->>'companyId') THEN
    RETURN;
  END IF;

  RAISE EXCEPTION 'Inspection lot % changes only through its inspection decision (Accept, Reject or Partial).',
    COALESCE(p_new->>'inspectionId', p_new->>'id');
END;
$function$;

CREATE OR REPLACE FUNCTION public.check_location_goods_in_storage_units(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
-- Goods-in inspection hold (spec .ai/specs/2026-11-03-goods-in-inspection-hold.md).
-- A location's inspection and rejected storage units must be its own, active
-- and non-nettable: the foreign keys only check that the unit exists, and held
-- stock in a nettable unit would be offered to MRP and picking. A company
-- restore or import sets one of the two flags. A plain RAISE (P0001), so the
-- API shows the text.
DECLARE
  v_column TEXT;
  v_unit   TEXT;
  v_found  RECORD;
BEGIN
  IF p_operation NOT IN ('INSERT', 'UPDATE') THEN
    RETURN;
  END IF;
  IF current_setting('app.inspection_release', true) = 'on'
     OR current_setting('app.sync_in_progress', true) = 'true' THEN
    RETURN;
  END IF;

  FOREACH v_column IN ARRAY ARRAY['inspectionStorageUnitId', 'rejectedStorageUnitId'] LOOP
    v_unit := p_new->>v_column;
    CONTINUE WHEN v_unit IS NULL;
    CONTINUE WHEN p_operation = 'UPDATE'
      AND v_unit IS NOT DISTINCT FROM p_old->>v_column
      AND (p_new->>'companyId') IS NOT DISTINCT FROM (p_old->>'companyId');

    SELECT su."name", su."active", su."effectiveNettable" INTO v_found
    FROM "storageUnit" su
    WHERE su."id" = v_unit
      AND su."companyId" = p_new->>'companyId'
      AND su."locationId" = p_new->>'id';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'The goods-in storage unit must belong to this location.';
    END IF;
    IF NOT COALESCE(v_found."active", true) THEN
      RAISE EXCEPTION '% is inactive. A goods-in storage unit must be active.', v_found."name";
    END IF;
    IF COALESCE(v_found."effectiveNettable", true) THEN
      RAISE EXCEPTION '% is nettable. A goods-in storage unit must be non-nettable.', v_found."name";
    END IF;
  END LOOP;
END;
$function$;

CREATE OR REPLACE FUNCTION public.check_nonconformance_inspection_link(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
-- Goods-in inspection hold (spec .ai/specs/2026-11-03-goods-in-inspection-hold.md).
-- A Partial untracked receipt lot holds its rejected remainder until its
-- linked NCR closes, and closing that NCR (closeIssue) writes the remainder
-- off. A direct link to an NCR that is already Closed would release the
-- remainder with no write-off; re-pointing or deleting the lot's link would
-- leave it held with no NCR to decide it. Only a posting that sets
-- app.inspection_release changes such a link; a company wipe, restore or
-- import sets one of the two flags, and deleting the company is never
-- refused. A plain RAISE (P0001), so the API shows the text.
DECLARE
  v_lot TEXT;
BEGIN
  IF p_operation = 'UPDATE'
     AND (p_new->'inspectionId') IS NOT DISTINCT FROM (p_old->'inspectionId')
     AND (p_new->'nonConformanceId') IS NOT DISTINCT FROM (p_old->'nonConformanceId') THEN
    RETURN;
  END IF;
  IF current_setting('app.inspection_release', true) = 'on'
     OR current_setting('app.sync_in_progress', true) = 'true' THEN
    RETURN;
  END IF;

  -- The lot this change takes the link from (re-point, unlink).
  IF p_operation IN ('UPDATE', 'DELETE') THEN
    SELECT COALESCE(i."inspectionId", i."id") INTO v_lot
    FROM "inspection" i
    JOIN "item" it ON it."id" = i."itemId" AND it."companyId" = i."companyId"
    WHERE i."id" = p_old->>'inspectionId'
      AND i."sourceDocument" = 'Receipt'
      AND i."status" = 'Partial'
      AND it."itemTrackingType" = 'Inventory'
      AND i."lotSize" - COALESCE(i."acceptedQuantity", 0) > 0
      AND public.inspection_lot_holds(i."id", i."status", i."acceptedQuantity");
    IF FOUND AND EXISTS (SELECT 1 FROM "company" c WHERE c."id" = p_old->>'companyId') THEN
      RAISE EXCEPTION 'Inspection lot % holds its rejected part until its NCR is completed. Complete the NCR instead of moving or removing its link.',
        v_lot;
    END IF;
  END IF;

  -- The lot this change links to an NCR that is already Closed.
  IF p_operation IN ('INSERT', 'UPDATE') THEN
    SELECT COALESCE(i."inspectionId", i."id") INTO v_lot
    FROM "inspection" i
    JOIN "item" it ON it."id" = i."itemId" AND it."companyId" = i."companyId"
    JOIN "nonConformance" nc
      ON nc."id" = p_new->>'nonConformanceId' AND nc."status" = 'Closed'
    WHERE i."id" = p_new->>'inspectionId'
      AND i."sourceDocument" = 'Receipt'
      AND i."status" = 'Partial'
      AND it."itemTrackingType" = 'Inventory'
      AND i."lotSize" - COALESCE(i."acceptedQuantity", 0) > 0
      AND public.inspection_lot_holds(i."id", i."status", i."acceptedQuantity");
    IF FOUND THEN
      RAISE EXCEPTION 'Inspection lot % holds its rejected part until its own NCR is completed. Link it to an open NCR.',
        v_lot;
    END IF;
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.check_nonconformance_inspection_release(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
-- Goods-in inspection hold (spec .ai/specs/2026-11-03-goods-in-inspection-hold.md).
-- A Partial receipt lot holds its rejected remainder until its NCR closes, and
-- closing the NCR (closeIssue) writes that remainder off. A direct status edit
-- (PostgREST) to Closed would release it with no write-off, and deleting the
-- NCR would leave it held with no NCR to decide it. Only closeIssue, which
-- sets app.inspection_release, closes such an NCR; a company wipe, restore or
-- import sets one of the two flags, and deleting the company is never refused.
-- A plain RAISE (P0001), so the API shows the text.
DECLARE
  v_ncr JSONB;
  v_lot TEXT;
BEGIN
  -- Hot path: only a change of status to Closed, or a delete.
  IF p_operation = 'UPDATE' THEN
    IF p_new->>'status' IS DISTINCT FROM 'Closed'
       OR p_old->>'status' IS NOT DISTINCT FROM 'Closed' THEN
      RETURN;
    END IF;
    v_ncr := p_new;
  ELSIF p_operation = 'DELETE' THEN
    IF p_old->>'status' IS NOT DISTINCT FROM 'Closed' THEN
      RETURN;
    END IF;
    v_ncr := p_old;
  ELSE
    RETURN;
  END IF;
  IF current_setting('app.inspection_release', true) = 'on'
     OR current_setting('app.sync_in_progress', true) = 'true' THEN
    RETURN;
  END IF;

  SELECT COALESCE(i."inspectionId", i."id") INTO v_lot
  FROM "nonConformanceInspection" nci
  JOIN "inspection" i ON i."id" = nci."inspectionId"
  JOIN "item" it ON it."id" = i."itemId" AND it."companyId" = i."companyId"
  WHERE nci."nonConformanceId" = v_ncr->>'id'
    AND i."sourceDocument" = 'Receipt'
    AND i."status" = 'Partial'
    AND it."itemTrackingType" = 'Inventory'
    AND i."lotSize" - COALESCE(i."acceptedQuantity", 0) > 0
    AND public.inspection_lot_holds(i."id", i."status", i."acceptedQuantity")
  ORDER BY 1
  LIMIT 1;
  IF NOT FOUND THEN
    RETURN;
  END IF;
  IF p_operation = 'DELETE' THEN
    -- A company deletion cascades here after the company row is gone.
    IF NOT EXISTS (SELECT 1 FROM "company" c WHERE c."id" = v_ncr->>'companyId') THEN
      RETURN;
    END IF;
    RAISE EXCEPTION 'This NCR holds the rejected part of inspection lot %. Complete the NCR to post its disposition instead of deleting it.',
      v_lot;
  END IF;
  RAISE EXCEPTION 'This NCR holds the rejected part of inspection lot %. Complete the NCR to post its disposition and close it.',
    v_lot;
END;
$function$;

CREATE OR REPLACE FUNCTION public.check_tracked_entity_inspection_hold(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
-- Goods-in inspection hold (spec .ai/specs/2026-11-03-goods-in-inspection-hold.md).
-- A serial or batch unit is held by its On Hold status while its receipt
-- line's lot is open, so a direct edit (PostgREST) could release it without a
-- decision. Only the postings that ARE the release (they set
-- app.inspection_release) change its status or its receipt line then. A plain
-- RAISE (P0001), so the API shows the text.
DECLARE
  v_line TEXT;
  v_item TEXT;
BEGIN
  -- Hot path: most updates are of units that are not On Hold.
  IF p_operation <> 'UPDATE' OR p_old->>'status' IS DISTINCT FROM 'On Hold' THEN
    RETURN;
  END IF;
  v_line := p_old->'attributes'->>'Receipt Line';
  IF v_line IS NULL THEN
    RETURN;
  END IF;
  IF p_new->>'status' = 'On Hold'
     AND (p_new->'attributes'->>'Receipt Line') IS NOT DISTINCT FROM v_line THEN
    RETURN;
  END IF;
  IF current_setting('app.inspection_release', true) = 'on'
     OR current_setting('app.sync_in_progress', true) = 'true' THEN
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1 FROM "inspection" i
    WHERE i."companyId" = p_old->>'companyId'
      AND i."sourceDocument" = 'Receipt'
      AND i."sourceDocumentLineId" = v_line
      AND i."status" IN ('Pending', 'In Progress')
  ) THEN
    SELECT "readableIdWithRevision" INTO v_item FROM "item" WHERE "id" = p_old->>'itemId';
    RAISE EXCEPTION '% % is held for inspection. Quality must decide its inspection lot before it can be released.',
      COALESCE(v_item, p_old->>'itemId', ''), COALESCE(p_old->>'readableId', p_old->>'id');
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_receipt_inspection_status(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
-- Keeps receipt."inspectionStatus" in step with the receipt's inspection lots
-- and its putaway transfers (spec .ai/specs/2026-11-03-goods-in-inspection-hold.md).
BEGIN
  IF p_table = 'inspection' THEN
    IF COALESCE(p_new->>'sourceDocument', p_old->>'sourceDocument') IS DISTINCT FROM 'Receipt' THEN
      RETURN;
    END IF;
    IF p_operation = 'UPDATE'
       AND p_new->>'status' IS NOT DISTINCT FROM p_old->>'status'
       AND p_new->>'acceptedQuantity' IS NOT DISTINCT FROM p_old->>'acceptedQuantity' THEN
      RETURN;
    END IF;
    PERFORM public.refresh_receipt_inspection_status(
      COALESCE(p_new->>'sourceDocumentId', p_old->>'sourceDocumentId')
    );
  ELSIF p_table = 'stockTransfer' THEN
    IF p_operation <> 'UPDATE' OR p_new->>'receiptId' IS NULL THEN
      RETURN;
    END IF;
    IF p_new->>'status' IS NOT DISTINCT FROM p_old->>'status' THEN
      RETURN;
    END IF;
    PERFORM public.refresh_receipt_inspection_status(p_new->>'receiptId');
  END IF;
END;
$function$;

-- event triggers (packages/database/src/event-system/attachments.ts)
SET lock_timeout = '5s';
SELECT set_event_triggers('inspection', ARRAY['check_inspection_lot_release']::text[], ARRAY['sync_receipt_inspection_status']::text[], false, ARRAY['broadcast_table_changes']::text[]);
SELECT set_event_triggers('itemLedger', ARRAY[]::text[], ARRAY[]::text[], false, ARRAY['apply_item_stock_quantities', 'broadcast_table_changes', 'check_inspection_hold', 'queue_kanban_level_checks']::text[]);
SELECT set_event_triggers('location', ARRAY['check_location_goods_in_storage_units']::text[], ARRAY['sync_create_location_related_records']::text[], true, ARRAY['broadcast_reference_changes']::text[]);
SELECT set_event_triggers('nonConformance', ARRAY['check_nonconformance_inspection_release']::text[], ARRAY['sync_advance_document_sequence']::text[], true, ARRAY['broadcast_table_changes']::text[]);
